div.div:
struct task_t
{
/* Address space description */
vm_map_t map;
};

struct vm_map_t
{
/* Physical map */
pmap_t pmap;
};

struct pmap_t
{
/* Physical page of the root translation table */
pmap_paddr_t ttep; // uint64_t
};

struct _EPROCESS
{
/* Process control block */
struct _KPROCESS Pcb;
};
